import{z as i,x as o,o as E,c as h,q as l,j as A,D as r,d as e,s,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"时序逻辑 LTL / CTL","description":"","frontmatter":{"title":"时序逻辑 LTL / CTL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ltl-ctl.md","filePath":"cs/ltl-ctl.md","lastUpdated":1791063341000}'),L={name:"cs/ltl-ctl.md"};function p(C,a,T,B,d,F){const m=o("Mermaid");return E(),h("div",null,[a[2]||(a[2]=l('<h1 id="时序逻辑-ltl-ctl" tabindex="-1">时序逻辑 LTL / CTL <a class="header-anchor" href="#时序逻辑-ltl-ctl" aria-label="Permalink to &quot;时序逻辑 LTL / CTL&quot;">​</a></h1><div class="epigraph"><p>LTL 谈路径上的 $\\mathrm{G},\\mathrm{F},\\mathrm{U}$；CTL 在状态上带路径量词 $\\mathrm{A},\\mathrm{E}$。二者不可比，CTL* 合起来。模型检验算法因此分家。</p><footer>—— 据 Pnueli, 1977；Clarke and Emerson；Baier and Katoen 整理</footer></div><p>上一课<a href="/cs/model-checking">模型检验</a> 有流程无性质语言。缺口是 <strong>LTL 与 CTL</strong>。安全 \\(\\mathrm{G}\\neg\\mathrm{bad}\\)、活性 \\(\\mathrm{GF}\\mathrm{progress}\\)。本课钉算子与表达力差，不写自动机表全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LTL：公式在无穷路径上解释。\\(\\mathrm{X}\\varphi\\) 下一状态，\\(\\varphi\\mathrm{U}\\psi\\) until，\\(\\mathrm{F}=\\top\\mathrm{U}\\)，\\(\\mathrm{G}=\\neg\\mathrm{F}\\neg\\)。系统满足 \\(\\varphi\\)：从初态出发<strong>所有</strong>路径满足（或带公平）。CTL：状态公式，\\(\\mathrm{EX},\\mathrm{EG},\\mathrm{EU},\\mathrm{AX},\\ldots\\)——先量词后时序。\\(\\mathrm{AF AG}p\\) 与 \\(\\mathrm{AGF}p\\) 一类不可互译。线性 vs 分支。</p><p><span class="marginnote">术语翻译：\\(\\mathrm{G}p\\) 读作「从此往后每一刻 \\(p\\) 都成立」；\\(\\mathrm{F}p\\) 读作「将来某一刻 \\(p\\) 会成立——可以晚，但不许永远缺席」；\\(p\\,\\mathrm{U}\\,q\\) 读作「\\(p\\) 一直撑到 \\(q\\) 到来的那一刻，且 \\(q\\) 必须真的到来」。</span></p><p>LTL 检验：公式 \\(\\to\\) Büchi 自动机，与系统同步，空性。PSPACE 完全。CTL：多项式于 \\(|M|\\times|\\varphi|\\) 的标记算法，用 \\(\\mu/\\nu\\)。</p><h3 id="不是「g-就是-always-英语」" tabindex="-1">不是「G 就是 always 英语」 <a class="header-anchor" href="#不是「g-就是-always-英语」" aria-label="Permalink to &quot;不是「G 就是 always 英语」&quot;">​</a></h3><p>没有量词的 LTL 仍隐含「所有路径」。CTL 的 \\(\\mathrm{EF}\\) 是存在路径。写错量词会把安全写成活性。</p><p><span class="marginnote">Pnueli 1977 LTL。Emerson–Clarke CTL。Baier–Katoen 第 5–6 章。Vardi–Wolper 自动机方法。本课不证表达力全部分离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用互斥：\\(\\mathrm{G}\\neg(c_1\\land c_2)\\) 安全；\\(\\mathrm{G}(try\\to\\mathrm{F}crit)\\) 活性。指出公平性：无公平则「永远不调度」是合法路径。对照 Hoare：安全可用不变式；活性要用变式或 \\(\\mathrm{F}\\)。</p>',12)),(E(),A(n,null,{default:r(()=>[s(m,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LTL%5B%22LTL%20%E8%B7%AF%E5%BE%84%E5%85%AC%E5%BC%8F%22%5D%20--%3E%20BA%5B%22B%C3%BCchi%20%E8%87%AA%E5%8A%A8%E6%9C%BA%22%5D%0A%20%20CTL%5B%22CTL%20%E7%8A%B6%E6%80%81%E5%85%AC%E5%BC%8F%22%5D%20--%3E%20MU%5B%22%CE%BC%2F%CE%BD%20%E6%A0%87%E8%AE%B0%22%5D%0A%20%20BA%20--%3E%20MC%5B%22%E6%A8%A1%E5%9E%8B%E6%A3%80%E9%AA%8C%22%5D%0A%20%20MU%20--%3E%20MC%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"性质语言选定之后，工具链分叉。工业上 LTL 常见（断言风格）；硬件 CTL/ACTL。CTL* 更贵。本课只要：写性质时先选线性还是分支。",-1)),a[5]||(a[5]=t("p",null,[t("a",{href:"/cs/alphabet-language"},"正则"),e(" 是有限串；这里无穷词，ω-正则。泵引理不直接搬。")],-1)),a[6]||(a[6]=t("p",null,"LTL 不能说「存在一条路径始终避免死锁且另一条……」那种分支比较；CTL 不能说「沿同一路径 \\(p\\) 直到 \\(q\\) 且中间无限常 \\(r\\)」的某些线性组合。CTL* 两者都收，检验更贵。\\(\\omega\\)-正则捕获 LTL；正则语言课的有限串泵引理不适用无穷词，另有无穷泵，本课不写。",-1)),a[7]||(a[7]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：LTL 像沿一条固定铁轨描述沿途风景——只谈这一条轨上的时刻序列。CTL 像站在岔路口看地图，可以问「存在一条路能到吗」（\\(\\mathrm{EF}\\)）或「每条路都会到吗」（\\(\\mathrm{AF}\\)）。量词与时序谁在前，就是两种语言的分水岭。")],-1)),(E(),A(n,null,{default:r(()=>[s(m,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%A6%81%E9%AA%8C%E8%AF%81%E7%9A%84%E6%80%A7%E8%B4%A8%22%5D%20--%3E%20Q1%7B%22%E5%85%B3%E5%BF%83%E6%AF%8F%E6%9D%A1%E6%89%A7%E8%A1%8C%2C%20%E8%BF%98%E6%98%AF%E5%AD%98%E5%9C%A8%E6%9F%90%E6%9D%A1%E6%89%A7%E8%A1%8C%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%AF%8F%E6%9D%A1%22%7C%20LTL%5B%22LTL%3A%20%E9%9A%90%E5%BC%8F%E5%85%A8%E8%B7%AF%E5%BE%84%E9%87%8F%E5%8C%96%22%5D%0A%20%20LTL%20--%3E%20SAFE%7B%22%E5%9D%8F%E4%BA%8B%E6%B0%B8%E4%B8%8D%E5%8F%91%E7%94%9F%3F%22%7D%0A%20%20SAFE%20--%3E%7C%22%E6%98%AF%22%7C%20GG%5B%22%E5%AE%89%E5%85%A8%3A%20G%20%C2%ACbad%22%5D%0A%20%20SAFE%20--%3E%7C%22%E5%90%A6%2C%20%E5%A5%BD%E4%BA%8B%E9%A1%BB%E5%8F%8D%E5%A4%8D%E5%88%B0%E6%9D%A5%22%7C%20GF%5B%22%E6%B4%BB%E6%80%A7%3A%20GF%20progress%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%AD%98%E5%9C%A8%E6%9F%90%E6%9D%A1%20%2F%20%E5%88%86%E6%94%AF%22%7C%20CTL%5B%22CTL%3A%20%E9%87%8F%E8%AF%8D%20A%20%E6%88%96%20E%20%E5%9C%A8%E5%89%8D%22%5D%0A%20%20CTL%20--%3E%20EF%5B%22%E4%BE%8B%3A%20EF%20reset%20%E5%AD%98%E5%9C%A8%E8%B7%AF%E5%BE%84%E5%8F%AF%E8%BE%BE%20reset%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写嵌套 until 的全部等价，不引入 MTL 实时。不把 STL 信号时序当主线。后课默认：安全 \\(\\mathrm{G}\\)、活性 \\(\\mathrm{F}/\\mathrm{GF}\\)；LTL 与 CTL 不可互换。下一课 SAT 引擎：DPLL/CDCL。</p><p>安全用 \\(\\mathrm{G}\\)，活性用 \\(\\mathrm{F}/\\mathrm{GF}\\)，公平性必须写进模型或公式。LTL 走 Büchi，CTL 走标记不动点，二者表达力不可比。有界展开把路径交给 SAT，下一课引擎。</p><p><span class="marginnote">常见误区：初学者容易把 \\(\\mathrm{AG\\,EF}\\,p\\)（每个状态都还「有希望」到 \\(p\\)）当成 \\(\\mathrm{AF\\,AG}\\,p\\)（终将永远 \\(p\\)）——前者只保证希望存在，系统可以永远不走那条路。量词顺序差一步，性质强弱天差地别，验证通过不等于符合直觉。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LTL：路径上 G/F/U；CTL：状态上 A/E + 时序。</li><li>检验：Büchi 空性 vs 标记不动点。</li><li>公平性是活性的一部分，须声明。</li><li>出处：Pnueli, 1977；Clarke and Emerson；Baier and Katoen。</li></ul>',6))])}const c=i(L,[["render",p]]);export{u as __pageData,c as default};
